CREATE TABLE chats (id TEXT PRIMARY KEY, title TEXT NOT NULL, updated_at INTEGER NOT NULL, is_out_of_context INTEGER NOT NULL DEFAULT 0, compaction TEXT);
           CREATE TABLE messages (row_id INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL, chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE, position INTEGER NOT NULL, role TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE (chat_id, id));
           CREATE TABLE attachments (message_row_id INTEGER NOT NULL REFERENCES messages(row_id) ON DELETE CASCADE, position INTEGER NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, blob_hash TEXT NOT NULL, PRIMARY KEY (message_row_id, position));
           CREATE TABLE blobs (hash TEXT PRIMARY KEY, bytes INTEGER NOT NULL);
           CREATE TABLE kv (key TEXT PRIMARY KEY, value TEXT NOT NULL);
           CREATE VIRTUAL TABLE message_search USING fts5(chat_id UNINDEXED, message_id UNINDEXED, body);
